INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (1, '本格豚こま肉じゃが', '豚肉', 40, 2, '甘辛い味がご飯に止まらない、定番の家庭料理。', '["豚こま切れ肉 200g", "じゃがいも 3個", "玉ねぎ 1個", "醤油 大さじ3", "砂糖 大さじ2", "みりん 大さじ2"]', '["じゃがいもは乱切り、玉ねぎはくし切りにする。", "鍋に油を熱し、豚肉と玉ねぎを炒める。", "じゃがいもを加えてさらに炒める。", "調味料を加え、落し蓋をして中火で15分煮る。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (2, 'とろとろ卵のオムライス', '卵', 25, 3, 'ケチャップライスをふわとろ卵で包んだ一品。', '["卵 3個", "ご飯 茶碗1杯", "鶏もも肉 50g", "玉ねぎ 1/4個", "ケチャップ 大さじ3"]', '["鶏肉と玉ねぎはみじん切りにする。", "フライパンで炒め、ご飯とケチャップを加える。", "別のフライパンで卵を半熟にし、包み込む。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (3, '初夏の冷やし中華', 'きゅうり', 20, 2, '夏に食べたい、さっぱりとした酸味が決め手。', '["中華麺 2玉", "ハム 4枚", "きゅうり 1本", "卵 2個", "醤油 大さじ2", "酢 大さじ3", "砂糖 大さじ2", "ごま油 大さじ1"]', '["中華麺を茹でて冷水で締める。", "ハムときゅうりは細切りにする。", "卵は薄焼き卵にして細切りにする。", "調味料を混ぜ合わせてタレを作り、かける。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (4, 'なすと豚ひき肉の味噌炒め', 'なす', 20, 2, 'とろとろのナスとピリ辛の味噌が絶妙に合う。', '["なす 3本", "豚ひき肉 150g", "にんにく・生姜 各1片", "味噌 大さじ2", "甜麺醤 大さじ1", "醤油 大さじ1", "砂糖 小さじ1"]', '["ナスは乱切りにして水にさらす。", "フライパンでナスを油で炒める。", "ひき肉とにんにく・生姜を炒め、調味料を加える。", "ナスを加えて煮込み、とろみをつける。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (5, 'とうもろこしの天ぷら', 'とうもろこし', 30, 3, '甘みが凝縮された、夏の天ぷら。', '["とうもろこし 1本", "薄力粉 100g", "冷水 150ml", "卵黄 1個", "天つゆ 適量"]', '["とうもろこしは茹でて粒をそぎ落とす。", "薄力粉、冷水、卵黄をさっくり混ぜて衣を作る。", "とうもろこしに衣をつけて170度の油で揚げる。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (6, 'オクラと豆腐のさっぱり和え', 'オクラ', 10, 1, '火を使わない、超時短ヘルシー副菜。', '["オクラ 5本", "木綿豆腐 1/2丁", "醤油 大さじ2", "ごま油 小さじ1", "かつお節 適量"]', '["オクラは板ずりして茹で、小口切りにする。", "豆腐は水切りをして器に盛る。", "オクラをのせ、醤油、ごま油、かつお節をかける。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (7, 'アジの南蛮漬け', 'アジ', 30, 2, '揚げた魚を甘酢に浸した、さっぱり料理。', '["アジ 2尾", "玉ねぎ 1/2個", "パプリカ 1/2個", "酢 大さじ3", "醤油 大さじ2", "砂糖 大さじ2", "水 大さじ2"]', '["アジは3枚におろし、食べやすい大きさに切る。", "玉ねぎとパプリカは薄切りにし、調味料に浸す。", "アジに片栗粉をまぶし、170度の油で揚げる。", "揚げたアジを調味料に浸し、冷蔵庫で冷やす。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (8, 'ピリ辛麻婆豆腐', '豆腐', 20, 2, '辛さと旨みが際立つ、中華の王道。', '["木綿豆腐 1丁", "豚ひき肉 150g", "長ねぎ 1/2本", "豆瓣醤 大さじ1", "甜麺醤 大さじ1", "醤油 大さじ1", "水 150ml", "片栗粉 大さじ1"]', '["豆腐は2cm角に切り、塩湯でさっと茹でる。", "ひき肉を炒め、調味料を加える。", "豆腐を加えて優しく煮込む。", "水溶き片栗粉でとろみをつける。"]', 0);
INSERT INTO recipe (recipe_id, name, main, time, diff, description, ingredients, steps, category) VALUES
  (9, 'チャーハン', '米', 15, 2, 'パラパラに仕上げるのがコツの鉄板料理。', '["ご飯 茶碗2杯", "卵 2個", "長ねぎ 1/2本", "ハム 2枚", "醤油 大さじ1", "塩コショウ 少々", "ごま油 大さじ1"]', '["卵は溶きほぐし、ねぎとハムはみじん切りにする。", "ごま油で卵を半熟にして取り出す。", "ねぎとハムを炒め、ご飯を加えてほぐす。", "卵を戻し、調味料で強火で炒め合わせる。"]', 0);
